using Volo.Abp.DependencyInjection;

namespace EHub.ShopManagement.AiAssistant;

/// <summary>
/// Hand-authored registry, one entry per Shop Management module, built directly from the real
/// Create*Dto classes (ShopUnitEditDtoBase, CreateUpdateShopCustomerDto, etc.) - see the comment on
/// each module for which file it mirrors. This is the ONLY place field names/types/requiredness
/// come from; nothing here is generated by or accepted from Ollama.
///
/// Fields deliberately NOT registered anywhere in this file (per the "must not include" list):
/// TenantId, audit fields (CreationTime/CreatorId/etc.), generated document numbers (Code is
/// listed as IsSystemGenerated for AI purposes even where the human UI lets a user type it - the
/// AI never invents one either), calculated balances, CurrentStock, posting user/date fields, and
/// backend-owned Status fields.
/// </summary>
public class ShopAiModuleMetadataProvider : IShopAiModuleMetadataProvider, ISingletonDependency
{
    private readonly List<ShopAiModuleMetadata> _modules;
    private readonly Dictionary<string, ShopAiModuleMetadata> _byKey;
    private readonly Dictionary<string, ShopAiModuleMetadata> _byAlias;

    public ShopAiModuleMetadataProvider()
    {
        _modules = BuildModules();
        _byKey = _modules.ToDictionary(m => m.ModuleKey, StringComparer.OrdinalIgnoreCase);
        _byAlias = new Dictionary<string, ShopAiModuleMetadata>(StringComparer.OrdinalIgnoreCase);
        foreach (var module in _modules)
        {
            _byAlias[module.ModuleKey] = module;
            _byAlias[module.DisplayName] = module;
            foreach (var alias in module.Aliases)
            {
                _byAlias.TryAdd(alias, module);
            }
        }
    }

    public ShopAiModuleMetadata GetModule(string moduleKey) =>
        _byKey.TryGetValue(moduleKey, out var m) ? m : throw new KeyNotFoundException($"Unknown ShopAi module key '{moduleKey}'.");

    public IReadOnlyList<ShopAiModuleMetadata> GetModules() => _modules;

    public bool TryGetModule(string moduleNameOrAlias, out ShopAiModuleMetadata? metadata)
    {
        if (string.IsNullOrWhiteSpace(moduleNameOrAlias))
        {
            metadata = null;
            return false;
        }

        return _byAlias.TryGetValue(moduleNameOrAlias.Trim(), out metadata);
    }

    public bool TryFindModuleInText(string text, out ShopAiModuleMetadata? metadata)
    {
        metadata = null;
        if (string.IsNullOrWhiteSpace(text)) return false;

        ShopAiModuleMetadata? best = null;
        var bestLength = 0;
        foreach (var module in _modules)
        {
            foreach (var candidate in new[] { module.ModuleKey, module.DisplayName }.Concat(module.Aliases))
            {
                // Skip very short tokens (e.g. "po") - they match too much unrelated text to be a
                // reliable signal on their own.
                if (string.IsNullOrWhiteSpace(candidate) || candidate.Length < 3) continue;
                if (candidate.Length > bestLength && text.Contains(candidate, StringComparison.OrdinalIgnoreCase))
                {
                    best = module;
                    bestLength = candidate.Length;
                }
            }
        }

        metadata = best;
        return best != null;
    }

    // ------------------------------------------------------------------
    // Field helpers
    // ------------------------------------------------------------------

    private static ShopAiFieldMetadata Field(
        string key, string display, string description, string dataType, bool required,
        string? example = null, bool isLookup = false, string? lookupModule = null,
        bool isSystemGenerated = false, bool isCalculated = false, decimal? min = null, decimal? max = null,
        int? maxLength = null, List<string>? allowedValues = null, List<string>? aliases = null,
        string? descriptionUrdu = null, string? descriptionRomanUrdu = null,
        string? askPromptEnglish = null, string? askPromptUrdu = null, string? askPromptRomanUrdu = null) => new()
    {
        FieldKey = key,
        DisplayName = display,
        Description = description,
        DescriptionUrdu = descriptionUrdu,
        DescriptionRomanUrdu = descriptionRomanUrdu,
        AskPromptEnglish = askPromptEnglish,
        AskPromptUrdu = askPromptUrdu,
        AskPromptRomanUrdu = askPromptRomanUrdu,
        DataType = dataType,
        IsRequired = required,
        IsLookup = isLookup,
        LookupModuleKey = lookupModule,
        IsSystemGenerated = isSystemGenerated,
        IsCalculated = isCalculated,
        IsUserEditable = !isSystemGenerated && !isCalculated,
        ExampleValue = example,
        MinimumValue = min,
        MaximumValue = max,
        MaximumLength = maxLength,
        AllowedValues = allowedValues ?? new List<string>(),
        Aliases = aliases ?? new List<string>(),
    };

