            CreateAction = ShopAiActionType.CreatePurchaseOrderDraft,
            RequiredPermission = EHubPermissions.ShopAiAssistant.CreatePurchaseOrderDraft,
            ExistingCreatePermission = EHubPermissions.ShopPurchaseOrders.Create,
            SupportsCreation = true,
            CreatesDraftOnly = true,
            Aliases = new() { "purchase order", "purchase orders", "po", "خریداری آرڈر", "purchase order add" },
            Fields = new()
            {
                Field("supplierId", "Supplier", "Which supplier the order is placed with.", "String", true, "ABC Traders", isLookup: true, lookupModule: "supplier"),
                Field("orderDate", "Order Date", "The date the order is placed.", "DateTime", true),
                Field("expectedDeliveryDate", "Expected Delivery Date", "Optional expected delivery date.", "DateTime", false),
                Field("supplierReference", "Supplier Reference", "Optional supplier-side reference number.", "String", false, maxLength: 128),
                Field("shippingCharges", "Shipping Charges", "Optional shipping cost.", "Decimal", false, "0", min: 0),
                Field("otherCharges", "Other Charges", "Optional other charges.", "Decimal", false, "0", min: 0),
                Field("notes", "Notes", "Optional notes.", "String", false, maxLength: 1000),
                Field("items", "Items", "One or more line items, each with a Product, Ordered Quantity, and Unit Purchase Price.", "List", true),
            },
            BusinessRules = new()
            {
                "At least one item is required.",
                "The AI creates the order as Draft only - approval, receiving goods, and any stock/ledger impact still happen through the normal Purchase Orders and Goods Receipts screens.",
            },
            RelatedModules = new() { "supplier", "product", "goodsreceipts" },
        });

        // Mirrors CreateShopSaleDto + CreateShopSaleItemDto.
        modules.Add(new ShopAiModuleMetadata
        {
            ModuleKey = "saledraft",
            DisplayName = "Sale",
            Description = "A Sale records products sold to a Customer. Created by the AI Assistant as a Draft only - it does not reduce stock or create customer ledger transactions until completed through the normal Sales/POS screen.",
            CreateAction = ShopAiActionType.CreateSaleDraft,
            RequiredPermission = EHubPermissions.ShopAiAssistant.CreateSaleDraft,
            ExistingCreatePermission = EHubPermissions.ShopSales.Create,
            SupportsCreation = true,
            CreatesDraftOnly = true,
            Aliases = new() { "sale", "sales", "pos", "فروخت", "sale add" },
            Fields = new()
            {
                Field("customerId", "Customer", "Which customer the sale is for.", "String", true, "Ali Traders", isLookup: true, lookupModule: "customer"),
                Field("saleDate", "Sale Date", "The date of the sale.", "DateTime", true),
                Field("dueDate", "Due Date", "Required for Credit sales - when payment is due.", "DateTime", false),
                Field("saleType", "Sale Type", "Cash or Credit.", "Enum", false, allowedValues: new() { "Cash", "Credit" }),
                Field("paymentMethod", "Payment Method", "How the customer paid.", "Enum", false, allowedValues: new() { "Cash", "Bank", "Card", "Cheque", "Other" }),
                Field("paidAmount", "Paid Amount", "Amount the customer paid immediately.", "Decimal", false, "0", min: 0),
                Field("referenceNumber", "Reference Number", "Optional reference number.", "String", false, maxLength: 128),
                Field("otherCharges", "Other Charges", "Optional other charges.", "Decimal", false, "0", min: 0),
                Field("notes", "Notes", "Optional notes.", "String", false, maxLength: 1000),
                Field("items", "Items", "One or more line items, each with a Product, Quantity, and Unit Sale Price.", "List", true),
            },
            BusinessRules = new()
            {
                "At least one item is required.",
                "The AI creates the sale as Draft only - stock reduction and customer ledger entries only happen when the sale is completed through the normal Sales/POS screen.",
            },
            RelatedModules = new() { "customer", "product", "customerpayments" },
        });

        // Mirrors CreateShopStockAdjustmentDto + CreateShopStockAdjustmentItemDto.
        modules.Add(new ShopAiModuleMetadata
        {
            ModuleKey = "stockadjustmentdraft",
            DisplayName = "Stock Adjustment",
            Description = "A Stock Adjustment corrects a product's stock quantity up or down (e.g. for damage or a count discrepancy). Created by the AI Assistant as a Draft only - it does not change stock until posted through the normal Stock Adjustments screen.",
            CreateAction = ShopAiActionType.CreateStockAdjustmentDraft,
            RequiredPermission = EHubPermissions.ShopAiAssistant.CreateStockAdjustmentDraft,
            ExistingCreatePermission = EHubPermissions.ShopStockAdjustments.Create,
            SupportsCreation = true,
            CreatesDraftOnly = true,
            Aliases = new() { "stock adjustment", "stock adjustments", "اسٹاک ایڈجسٹمنٹ", "stock adjustment add" },
            Fields = new()
            {
                Field("adjustmentDate", "Adjustment Date", "The date of the adjustment.", "DateTime", true),
                Field("reason", "Reason", "The overall reason for the adjustment.", "Enum", true, allowedValues: new() { "Damaged", "Lost", "Expired", "CountCorrection", "Other" }),
                Field("reasonDetails", "Reason Details", "Optional extra detail about the reason.", "String", false, maxLength: 500),
                Field("notes", "Notes", "Optional notes.", "String", false, maxLength: 1000),
                Field("items", "Items", "One or more line items, each with a Product, Adjustment Type (Increase/Decrease), and Adjustment Quantity.", "List", true),
            },
            BusinessRules = new()
            {
                "At least one item is required; adjustment quantity must be greater than zero per item.",
                "The AI creates the adjustment as Draft only - stock is only changed once it is posted through the normal Stock Adjustments screen.",
            },
            RelatedModules = new() { "product", "stocktransactions", "productbatches" },
        });

        // Mirrors CreateShopStockCountDto.
        modules.Add(new ShopAiModuleMetadata
        {
            ModuleKey = "physicalstockcountdraft",
            DisplayName = "Physical Stock Count",
            Description = "A Physical Stock Count is a session for counting actual stock on hand and reconciling it against system quantities, for either all products or a chosen scope. Created by the AI Assistant as a Draft only - counting and posting still happen through the normal Stock Counts screen.",
            CreateAction = ShopAiActionType.CreatePhysicalStockCountDraft,
            RequiredPermission = EHubPermissions.ShopAiAssistant.CreatePhysicalStockCountDraft,
            ExistingCreatePermission = EHubPermissions.ShopStockCounts.Create,
            SupportsCreation = true,
            CreatesDraftOnly = true,
            Aliases = new() { "stock count", "physical stock count", "اسٹاک کاؤنٹ", "stock count add" },
            Fields = new()
            {
                Field("countDate", "Count Date", "The date of the count.", "DateTime", true),
                Field("scope", "Scope", "Whether to count all products or a chosen subset.", "Enum", true, allowedValues: new() { "AllProducts", "Category", "SelectedProducts" }),
                Field("productCategoryId", "Category", "Required when Scope is Category.", "String", false, isLookup: true, lookupModule: "productcategory"),
                Field("selectedProductIds", "Selected Products", "Required when Scope is SelectedProducts.", "List", false, isLookup: true, lookupModule: "product"),
                Field("notes", "Notes", "Optional notes.", "String", false, maxLength: 1000),
            },
            BusinessRules = new()
            {
                "The AI creates the count session as Draft only - actual counting and any resulting stock correction happen through the normal Stock Counts screen.",
            },
            RelatedModules = new() { "product", "productcategory", "stocktransactions" },
        });

        // ---------------- Explanation-only modules (no AI creation this round) ----------------

        modules.Add(ExplainOnly("shopsettings", "Shop Settings", "Shop-wide configuration such as the shop's display name, currency code/symbol, decimal places, and tax settings. Every report and dashboard figure is formatted using these settings.", new() { "settings", "shop settings" }));

        modules.Add(ExplainOnly("sales", "Sales / POS", "The point-of-sale screen where a completed sale is finalized: stock is reduced, the customer ledger is updated, and payment status is tracked. This is the 'real' counterpart to the AI's Sale draft - a draft created by the AI must still be opened here to complete it.", new() { "pos", "point of sale" }, related: new() { "saledraft", "customer", "product" }));

        modules.Add(ExplainOnly("goodsreceipts", "Goods Receipts", "Records goods actually received against a Purchase Order. Completing a Goods Receipt increases stock and creates a supplier ledger transaction.", new() { "goods receipt", "receiving" }, related: new() { "purchaseorderdraft", "supplier", "stocktransactions" }));

        modules.Add(ExplainOnly("supplierpayments", "Supplier Payments", "Records money paid to a supplier and allocates it against outstanding Goods Receipts. Posting a payment reduces the supplier's payable balance.", new() { "supplier payment" }, related: new() { "supplier", "supplierledger", "bankaccount" }));

        modules.Add(ExplainOnly("purchasereturns", "Purchase Returns", "Records goods returned to a supplier from a completed Goods Receipt. Completing a return reduces stock and adjusts the supplier ledger.", new() { "purchase return" }, related: new() { "goodsreceipts", "supplier" }));

        modules.Add(ExplainOnly("supplierledger", "Supplier Ledger", "A running statement of everything owed to (or advanced to) a supplier - opening balance, purchases, payments, and returns - with a running balance.", new() { "supplier ledger", "supplier statement" }, related: new() { "supplier", "goodsreceipts", "supplierpayments", "purchasereturns" }));

        modules.Add(ExplainOnly("customerpayments", "Customer Payments", "Records money received from a customer and allocates it against one or more completed Sales. Posting a payment reduces the sales' pending balance.", new() { "customer payment" }, related: new() { "customer", "customerledger", "bankaccount" }));

        modules.Add(ExplainOnly("salereturns", "Sale Returns", "Records products returned by a customer from a completed Sale. Completing a return increases stock back and adjusts the customer ledger (refund or customer credit).", new() { "sale return" }, related: new() { "sales", "customer" }));

        modules.Add(ExplainOnly("customerledger", "Customer Ledger", "A running statement of everything a customer owes (or has as credit) - opening balance, sales, payments, and returns - with a running balance.", new() { "customer ledger", "customer statement" }, related: new() { "customer", "sales", "customerpayments", "salereturns" }));

        modules.Add(ExplainOnly("expenses", "Expenses", "Records shop expenses such as rent or utilities. A Draft expense can be created by the AI, but only reduces cash/bank balance once posted from this screen.", new() { "expenses list" }, related: new() { "expensedraft", "expensecategory", "cashregisters", "bankaccount" }));

        modules.Add(ExplainOnly("cashregisters", "Cash Registers", "Physical or logical cash drawers the shop uses to take in and pay out cash. Every cash-affecting transaction (sale payment, expense, etc.) posts against a cash register.", new() { "cash register", "till" }, related: new() { "cashtransactions", "cashclosings" }));

        modules.Add(ExplainOnly("cashtransactions", "Cash Transactions", "The full movement history (in and out) for a cash register, including manual adjustments as well as transactions generated automatically by sales, payments, and expenses.", new() { "cash transaction", "cash movement" }, related: new() { "cashregisters" }));

        modules.Add(ExplainOnly("cashclosings", "Daily Cash Closing", "The end-of-day process of counting actual cash in a register and reconciling it against the system-expected balance.", new() { "cash closing", "daily closing", "day end" }, related: new() { "cashregisters", "cashtransactions" }));

        modules.Add(ExplainOnly("banktransactions", "Bank Transactions", "The full movement history (in and out) for a bank account, including manual adjustments as well as transactions generated automatically by payments and expenses.", new() { "bank transaction", "bank movement" }, related: new() { "bankaccount" }));

        modules.Add(ExplainOnly("banktransfers", "Bank Transfers", "Moves money between two of the shop's own bank accounts. Posting a transfer debits one account and credits the other.", new() { "bank transfer", "fund transfer" }, related: new() { "bankaccount" }));

        modules.Add(ExplainOnly("stocktransactions", "Stock Transactions", "The full audit trail of every stock quantity change for every product - goods received, sales, returns, adjustments, and stock counts - each showing quantity in/out and running balance.", new() { "stock transaction", "stock movement", "inventory movement" }, related: new() { "product", "goodsreceipts", "sales", "stockadjustmentdraft" }));

        modules.Add(ExplainOnly("productbatches", "Product Batches / Expiry", "Tracks individual batches of a product (batch number, expiry date, quantity) for products with batch or expiry tracking enabled, used for FEFO allocation and expiry alerts.", new() { "batch", "batches", "expiry", "expiry management" }, related: new() { "product", "stocktransactions" }));

        modules.Add(ExplainOnly("dashboard", "Dashboard", "A read-only summary view of today's/this period's sales, expenses, balances, low-stock and near-expiry alerts, top products, and recent transactions.", new() { "dashboard", "overview" }, related: new() { "sales", "expenses" }));

        modules.Add(ExplainOnly("reports", "Reports", "A collection of read-only reports covering sales, purchases, stock, customer/supplier receivables and payables, expenses, cash, bank, tax summary, and product performance.", new() { "reports", "reporting" }));

        modules.Add(ExplainOnly("aiassistant", "AI Assistant", "This chat assistant itself - it can answer questions about any Shop Management module and guide you through creating a limited set of records, always asking for confirmation before creating anything.", new() { "ai assistant", "assistant", "chatbot" }));

        return modules;
    }

    private static ShopAiModuleMetadata ExplainOnly(string key, string displayName, string description, List<string> aliases, List<string>? related = null) => new()
    {
        ModuleKey = key,
        DisplayName = displayName,
        Description = description,
        SupportsCreation = false,
        RequiresConfirmation = false,
        RequiredPermission = string.Empty,
        ExistingCreatePermission = string.Empty,
        Aliases = aliases,
        RelatedModules = related ?? new List<string>(),
    };
}
